CREATE TABLE IF NOT EXISTS gis_authoritative_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_key text NOT NULL UNIQUE, source_name text NOT NULL, source_url text NOT NULL, authority_level text NOT NULL DEFAULT 'PENDING', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_evidence_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES gis_authoritative_sources(id) ON DELETE CASCADE, retrieved_at timestamptz NOT NULL DEFAULT now(), http_status integer, content_type text, content_hash text, snapshot_url text, verification_status text NOT NULL DEFAULT 'UNVERIFIED', notes text);